40	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
41	async function uniqueReferralCode(): Promise<string> {
42	  for (let i = 0; i < 6; i++) {
43	    const code = generateReferralCode();
44	    const clash = await db.user.findUnique({ where: { referralCode: code } });
45	    if (!clash) return code;
46	  }
47	  // Extremely unlikely; fall back to a longer code.
48	  return generateReferralCode(12);
49	}
