51	async function audit(userId: string | null, action: string, detail?: string) {
52	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
53	  // actions taken during impersonation aren't logged as if the customer did them.
54	  const imp = await impersonating();
55	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
56	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
57	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
58	}
