218	/**
219	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
220	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
221	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
222	 */
223	async function serverLimitError(userId: string): Promise<string | null> {
224	  const cap = await getSettingInt("max_servers_per_user", 10);
225	  if (cap <= 0) return null; // 0 (or negative) = unlimited
226	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
227	  if (owned >= cap) {
228	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
229	  }
230	  return null;
231	}
