233	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
234	  const user = await requireUser();
235	  // Spend path: never move a customer's money while an admin is impersonating them.
236	  await assertNotImpersonating();
237	  // Refuse new orders once the user is at their server cap.
238	  const limitErr = await serverLimitError(user.id);
239	  if (limitErr) return { error: limitErr };
240	  const parsed = orderSchema.safeParse({
241	    planId: formData.get("planId"),
242	    osTemplateId: formData.get("osTemplateId"),
243	    hostname: formData.get("hostname"),
244	  });
245	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
246	
247	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
248	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
249	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
250	
251	  // Image requirements (control panels/apps need more resources)
252	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
253	    return {
254	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
255	    };
256	  }
257	
258	  const cap = await capacityCheck(plan.id);
259	  if (!cap.ok) return { error: cap.reason };
260	
261	  // Optional: node (location) selection, else auto-schedule
262	  const requestedNodeId = String(formData.get("nodeId") ?? "");
263	  let nodeId: string | null = null;
264	  if (requestedNodeId) {
265	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
266	    if (!n) return { error: "Selected location is not available." };
267	    nodeId = n.id;
268	  } else {
269	    const n = await scheduleNode(plan.ramMB);
270	    nodeId = n?.id ?? null;
271	  }
272	
273	  // Add-ons (booleans)
274	  const addons = {
275	    malwareScanner: formData.get("addon_malware") === "1",
276	    dailyBackup: formData.get("addon_backup") === "1",
277	    docker: formData.get("addon_docker") === "1",
278	  };
279	
280	  // Optional SSH key added at deploy time
281	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
282	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
283	
284	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
285	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
286	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
287	  const ipCents = wantsDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
288	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
289	  // Mirrors lib/order.ts orderQuote so every VPS charge path agrees. Renewals in
290	  // worker/billing.ts bill the regular vpsTermPriceCents (untouched), so the
291	  // strikethrough shown on marketing pages is the real renewal price and this
292	  // discounted value is the real first-term price — displayed === charged.
293	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
294	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
295	  const promo = currentPromo(new Date());
296	  const chargeCents = promoPriceCents(regularPlanCents, promo) + ipCents;
297	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
298	
299	  const isAdmin = user.role === "ADMIN";
300	  const freeRequested = formData.get("free") === "1" && isAdmin;
301	
302	  if (!freeRequested && user.balanceCents < chargeCents) {
303	    return { error: "Insufficient balance. Top up your wallet first." };
304	  }
305	
306	  let server;
307	  try {
308	    server = await db.$transaction(async (tx) => {
309	    if (!freeRequested) {
310	      await debitWallet(tx, user.id, chargeCents);
311	      await tx.walletTransaction.create({
312	        data: {
313	          userId: user.id,
314	          amountCents: -chargeCents,
315	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
316	        },
317	      });
318	      // PAID invoice for the initial order (one distinct charge per order — the
319	      // new server row is created below, so there is no replay to dedupe).
320	      await tx.invoice.create({
321	        data: invoiceCreateData({
322	          userId: user.id,
323	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
324	          status: "PAID",
325	          period: { start: new Date(), end: addMonths(new Date(), term.months) },
326	          lineItems: [
327	            { description: `${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
328	          ],
329	        }),
330	      });
331	    }
332	    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
333	      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
334	      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
335	    }
336	    const s = await tx.server.create({
337	      data: {
338	        name: parsed.data.hostname,
339	        hostname: parsed.data.hostname,
340	        userId: user.id,
341	        planId: plan.id,
342	        osTemplateId: os.id,
343	        nodeId,
344	        addons,
345	        termMonths: term.months,
346	        wantsDedicatedIp,
347	        isFree: freeRequested,
348	        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
349	      },
350	    });
351	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
352	    return s;
353	    });
354	  } catch (e) {
355	    if (e instanceof InsufficientBalanceError) {
356	      return { error: "Insufficient balance. Top up your wallet first." };
357	    }
358	    throw e;
359	  }
360	
361	  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
362	  // A first paid order can unlock a referral reward (free admin grants don't count).
363	  if (!freeRequested) {
364	    try {
365	      await maybeRewardReferral(user.id);
366	    } catch { /* non-fatal */ }
367	  }
368	  redirect(`/dashboard/servers/${server.id}`);
369	}
