437	async function ownedServer(serverId: string) {
438	  const user = await requireUser();
439	  const server = await db.server.findUnique({ where: { id: serverId } });
440	  if (!server) throw new Error("Not found");
441	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
442	  return { user, server };
443	}
