445	export async function serverAction(serverId: string, action: string) {
446	  const { user, server } = await ownedServer(serverId);
447	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
448	    start: "START",
449	    stop: "STOP",
450	    reboot: "REBOOT",
451	    reinstall: "REINSTALL",
452	    delete: "DELETE",
453	  };
454	  const type = allowed[action];
455	  if (!type) throw new Error("Invalid action");
456	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
457	    throw new Error("Server is suspended");
458	  }
459	
460	  // A reinstall wipes the whole VM, including any block-storage volume the VM
461	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
462	  //
463	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
464	  // deliberately keeps `serverId` set so the volume can be re-attached
465	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
466	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
467	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
468	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
469	  // Reinstall — both guards see zero attached volumes, and the purge takes the
470	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
471	  // by serverId; this path did not. That asymmetry was the bug.
472	  if (type === "REINSTALL") {
473	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
474	    if (pinnedVolumes > 0) {
475	      throw new Error(
476	        "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
477	      );
478	    }
479	  }
480	
481	  const pending = await db.job.count({
482	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
483	  });
484	  if (pending > 0) return; // debounce: one job at a time per server
485	
486	  if (type === "DELETE") {
487	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
488	  }
489	  await db.job.create({ data: { type, serverId } });
490	  await audit(user.id, `server.${action}`, serverId);
491	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
492	  revalidatePath(`/dashboard/servers/${serverId}`);
493	}
