495	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
496	
497	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
498	  const user = await requireUser();
499	  // Spend/credit path: block while impersonating so an admin can't mint or move
500	  // a customer's balance on their behalf.
501	  await assertNotImpersonating();
502	  // Security: never mint free wallet balance in production. The demo gateway that
503	  // credits without a real payment is only ever acceptable in non-production, and
504	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
505	  if (process.env.NODE_ENV === "production") {
506	    return { error: "Please add funds with a card via the secure checkout." };
507	  }
508	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
509	  // go through Checkout.
510	  const { stripeConfigured } = await import("./stripe");
511	  if (stripeConfigured()) {
512	    return { error: "Please add funds with a card via the secure checkout." };
513	  }
514	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
515	  const topupHdrs = await headers();
516	  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
517	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
518	  if (!topupRl.ok) {
519	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
520	  }
521	  const amount = Number(formData.get("amount"));
522	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
523	    return { error: "Amount must be between $1 and $1000." };
524	  }
525	  const cents = Math.round(amount * 100);
526	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
527	  const minTopup = await getSettingInt("min_topup_cents", 500);
528	  if (cents < minTopup) {
529	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
530	  }
531	
532	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
533	  // sets. applyCouponToTopup re-validates for this user against the real amount.
534	  const jar = await cookies();
535	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
536	  let bonusCents = 0;
537	  let couponId: string | null = null;
538	  let couponLabel = "";
539	  if (couponCode) {
540	    const result = await applyCouponToTopup(couponCode, cents);
541	    if (result.ok) {
542	      bonusCents = result.bonusCents;
543	      couponId = result.couponId;
544	      couponLabel = result.label;
545	    } else {
546	      // REFUSE, don't silently drop. The old code fell through and completed the
547	      // top-up with no bonus and no message, so a code that passed validation at
548	      // the preview amount but fails against the real one (a `minAmountCents`
549	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
550	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
551	      // charged at this point, so stopping is free and the customer can retry
552	      // without the code or with a larger amount.
553	      return {
554	        error:
555	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
556	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
557	      };
558	    }
559	  }
560	
561	  await db.$transaction([
562	    db.user.update({
563	      where: { id: user.id },
564	      data: { balanceCents: { increment: cents + bonusCents } },
565	    }),
566	    db.walletTransaction.create({
567	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
568	    }),
569	    ...(bonusCents > 0 && couponId
570	      ? [
571	          db.walletTransaction.create({
572	            data: {
573	              userId: user.id,
574	              amountCents: bonusCents,
575	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
576	            },
577	          }),
578	          db.couponRedemption.create({
579	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
580	          }),
581	          db.coupon.update({
582	            where: { id: couponId },
583	            data: { timesRedeemed: { increment: 1 } },
584	          }),
585	        ]
586	      : []),
587	  ]);
588	  jar.delete(COUPON_COOKIE);
589	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
590	  // First successful paid action may unlock a referral reward for both parties.
591	  try {
592	    await maybeRewardReferral(user.id);
593	  } catch { /* non-fatal */ }
594	  revalidatePath("/dashboard/billing");
595	  return {};
596	}
