781	export async function adminSuspendServer(serverId: string, suspend: boolean) {
782	  const admin = await requireAdmin();
783	  // Record WHY. An admin suspension is NOT an unpaid one: the renewal sweep skips
784	  // suspended servers, so a paid-up customer suspended here is never charged and
785	  // never warned — and before `suspendReason` existed, `terminateOverdue` then
786	  // deleted their VM and all its data once the untouched term lapsed. Tagging it
787	  // ADMIN keeps the terminator away from it and stops "Renew now" silently
788	  // reversing an administrative decision.
789	  await db.server.update({
790	    where: { id: serverId },
791	    data: suspend
792	      ? { suspendReason: "ADMIN", suspendedNote: "suspended by support — contact us to restore access" }
793	      : { suspendReason: null, suspendedNote: null },
794	  });
795	  await db.job.create({ data: { type: suspend ? "SUSPEND" : "UNSUSPEND", serverId } });
796	  await audit(admin.id, suspend ? "admin.suspend_server" : "admin.unsuspend_server", serverId);
797	  revalidatePath("/admin/servers");
798	}
